package com.hbm.client.generator.industrialmemorial;
import com.hbm.machine.generator.industrialmemorial.*;import com.hbm.client.gui.font.LegacyFonts;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.extensions.common.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class IndustrialMemorialClient {
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(IndustrialMemorialContent.ENTITY.get(),IndustrialMemorialRenderer::new);}@SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){event.registerItem(new IClientItemExtensions(){private IndustrialMemorialItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){return renderer==null?(renderer=new IndustrialMemorialItemRenderer()):renderer;}},IndustrialMemorialContent.ITEM.get());}
 @EventBusSubscriber(modid="hbm",value=Dist.CLIENT)public static final class Overlay{@SubscribeEvent public static void overlay(RenderGuiEvent.Post event){var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.level==null||!(mc.hitResult instanceof BlockHitResult hit)||!mc.level.getBlockState(hit.getBlockPos()).is(IndustrialMemorialContent.BLOCK.get()))return;var g=event.getGuiGraphics();int x=g.guiWidth()/2+8,y=g.guiHeight()/2-10;g.drawString(LegacyFonts.get(),Component.translatable("gui.hbm.industrial_memorial.title"),x,y,0xff8000,true);g.drawString(LegacyFonts.get(),Component.translatable("gui.hbm.industrial_memorial.text"),x,y+12,0xffffff,true);}}
}
